SELECT rm.Id, rm.DisplayName, rm.ModelIdentifier, rm.ImageEditorDiffusionModel, rm.ImageEditorTextEncoder, rm.ImageEditorVae, rm.ImageEditorGraphKind, rm.ImageEditorSteps, rm.ImageEditorCfg, rm.ImageEditorSampler, rm.ImageEditorScheduler, rm.ImageEditorDenoise, rm.ImageEditorAuraFlowShift, rm.ImageEditorCfgNormStrength, rm.ImageEditorLoraName, rm.ImageEditorLoraStrength FROM RegisteredModels rm WHERE rm.ImageEditorDiffusionModel IS NOT NULL OR rm.ImageEditorSteps IS NOT NULL OR rm.ImageEditorCfg IS NOT NULL ORDER BY rm.DisplayName;
